   "orig": "This Cookbook Author Explores Cemeteries for Recipes To Die For",
   "lead": "L'autrice di libri di cucina Rosie Grant ha viaggiato per gli Stati Uniti alla ricerca di ricette originali incise sulle lapidi dei cimiteri. Secondo Bon Appétit, il suo lavoro ha portato alla luce un patrimonio di storie che celebra la comunità, l'eredità familiare e l'amore. Lo riferisce Bon Appétit.",
   "more": [],
