   "titolo": "L'AIEA preleva campioni d'acqua trattata ALPS a Fukushima Daiichi",
   "orig": "IAEA-led Team Samples ALPS-Treated Water at Fukushima Daiichi Nuclear Power Station under Additional Measures",
   "lead": "Un team guidato dall'Agenzia internazionale per l'energia atomica ha condotto un nuovo prelievo di campioni dell'acqua trattata con il sistema ALPS presso la centrale nucleare di Fukushima Daiichi, in Giappone, nell'ambito delle misure aggiuntive di monitoraggio concordate per garantire la sicurezza dello scarico in mare dell'acqua trattata. L'attività rientra nel programma di supervisione indipendente che l'AIEA porta avanti dall'inizio delle operazioni di rilascio. Lo riferisce Agenzia internazionale per l'energia atomica (Aiea).",
   "more": [
    "Fukushima Daiichi è la centrale nucleare giapponese danneggiata dal terremoto e dallo tsunami del 2011; da anni l'acqua usata per raffreddare i reattori viene trattata con il sistema ALPS per rimuovere le sostanze radioattive prima di essere rilasciata in mare, sotto il monitoraggio dell'AIEA."
   ],
