   "lead": "Il Ministero dell'Istruzione e del Merito ha pubblicato una nota, datata 15 ottobre 2026, con indicazioni sugli adempimenti amministrativi legati al servizio di supporto psicologico AscoltaMI, destinato agli studenti e attivo dal 28 maggio 2026 sulla piattaforma Unica. La nota fornisce alle segreterie scolastiche istruzioni precise su fatturazione e pagamenti relativi al servizio, accompagnate da un'infografica esplicativa. Lo riferisce Orizzonte Scuola.",
