   "lead": "Una nuova causa legale accusa il colosso delle prenotazioni Expedia di aver violato le leggi antitrust federali statunitensi, costringendo milioni di clienti a spendere fino al 30% in più per i soggiorni in hotel. La denuncia solleva interrogativi sulle pratiche commerciali della piattaforma nel settore delle prenotazioni online. Lo riferisce The New York Times.",
